function loadQuilljs(isEnabled = true, selector = null, options = null) {
    if (selector) {
        var elements = Array.prototype.slice.call(document.querySelectorAll(selector));
    } else {
        var elements = Array.prototype.slice.call(document.querySelectorAll('[data-quilljs]'));
    }
    elements.forEach(function (el) {
        if (selector && el.hasAttribute("data-quilljs")) {
            return;
        }
        var type = el.type;
        if (type == 'textarea') {
            value = el.value;
            container = document.createElement('div');
            container.innerHTML = value;
            el.parentNode.insertBefore(container, el.nextSibling);
            el.style.display = "none";
            var placeholder = el.placeholder;
        } else {
            var placeholder = null;
            container = el;
        }

        var toolbarOptions = [
            ['bold', 'italic', 'underline', 'strike'],
            [{ 'color': ["#000000", "#e60000", "#ff9900", "#ffff00", "#008a00", "#0066cc", "#9933ff", "#ffffff", "#facccc", "#ffebcc", "#ffffcc", "#cce8cc", "#cce0f5", "#ebd6ff", "#bbbbbb", "#f06666", "#ffc266", "#ffff66", "#66b966", "#66a3e0", "#c285ff", "#888888", "#a10000", "#b26b00", "#b2b200", "#006100", "#0047b2", "#6b24b2", "#444444", "#5c0000", "#663d00", "#666600", "#003700", "#002966", "#3d1466", 'custom-color'] }],
            ['blockquote', 'code-block'],
            [{ 'header': 1 }, { 'header': 2 }],            
            [{ 'list': 'ordered' }, { 'list': 'bullet' }],
            [{ 'script': 'sub' }, { 'script': 'super' }],    
            [{ 'indent': '-1' }, { 'indent': '+1' }],      
            [{ 'direction': 'rtl' }],                        
            [{ 'size': ['small', false, 'large', 'huge'] }],  
            [{ 'header': [1, 2, 3, 4, 5, 6, false] }],
            ['link', 'image', 'video', 'formula'],         
            [{ 'color': [] }, { 'background': [] }],         
            [{ 'font': [] }],
            [{ 'align': [] }],
            ['clean']                                         
        ];

        if (!options) {
            var defaults = {
                theme: 'snow',
                placeholder: placeholder,
                modules: {
                    imageResize: {
                        displaySize: true
                    },
                    toolbar: toolbarOptions
                },
            };
        } else {
            if (!options.placeholder) {
                options.placeholder = placeholder;
            }
            var defaults = options;
        }

        var editor = new Quill(container, defaults);
        editor.on('text-change', function () {
            var text = editor.root.innerHTML;
            el.value = text;
        });
        editor.enable(isEnabled);
    });
}
